package org.dextur.reputation.paper;
import java.util.*;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.inventory.*;
import org.bukkit.inventory.*;
import org.dextur.reputation.api.*;
import org.dextur.reputation.application.*;

/** Separate rehabilitation screen, reached from the existing profile or /rep recovery. */
final class RecoveryGui implements Listener {
    record Layout(boolean enabled,int entrySlot,int size,List<Integer> content,int summary,int start,int cancel,int back,int close,Material icon,Material objective,Material completed,Material startIcon,Material cancelIcon){
        static Layout load(java.nio.file.Path dir)throws Exception{var y=TierConfiguration.map(TierConfiguration.configuration(dir,"gui.yml").get("recovery-panel"));int size=YamlFiles.number(y,"size",45,54);if(size%9!=0)throw new IllegalArgumentException("Recovery GUI size");var used=new HashSet<Integer>();var slots=new ArrayList<Integer>();for(Object n:(List<?>)y.get("content-slots")){if(!(n instanceof Integer i)||i<0||i>=size||!used.add(i))throw new IllegalArgumentException("Recovery GUI content");slots.add(i);}if(slots.size()<32)throw new IllegalArgumentException("Recovery GUI requires 32 objective slots");var buttons=new ArrayList<Integer>();for(String key:List.of("summary-slot","start-slot","cancel-slot","back-slot","close-slot")){int n=YamlFiles.number(y,key,0,size-1);if(!used.add(n))throw new IllegalArgumentException("Recovery GUI overlapping slots");buttons.add(n);}return new Layout(YamlFiles.flag(y,"enabled"),YamlFiles.number(y,"entry-slot",0,53),size,List.copyOf(slots),buttons.get(0),buttons.get(1),buttons.get(2),buttons.get(3),buttons.get(4),material(y,"material"),material(y,"objective-material"),material(y,"completed-material"),material(y,"start-material"),material(y,"cancel-material"));}
        private static Material material(Map<String,Object> y,String key){var material=Material.matchMaterial(YamlFiles.text(y,key));if(material==null||!material.isItem()||material.isAir())throw new IllegalArgumentException("Invalid recovery GUI material");return material;}
    }
    static final class Session implements InventoryHolder{final UUID owner;final Map<Integer,Runnable> actions=new HashMap<>();Inventory inventory;boolean busy;long lastClick;Session(UUID id){owner=id;}public Inventory getInventory(){return inventory;}}
    private final DexturReputationPlugin plugin;private final RecoveryService service;private final RecoveryCommands commands;private final Messages messages;private final Layout layout;private final org.dextur.reputation.domain.recovery.RecoveryRules rules;private VotingGui voting;
    RecoveryGui(DexturReputationPlugin plugin,RecoveryService service,RecoveryCommands commands,Messages messages,Layout layout,org.dextur.reputation.domain.recovery.RecoveryRules rules){this.plugin=plugin;this.service=service;this.commands=commands;this.messages=messages;this.layout=layout;this.rules=rules;}
    void voting(VotingGui voting){this.voting=voting;}
    void attach(Player player,VotingGui.Session session){if(!layout.enabled()||!player.getUniqueId().equals(session.target)||!commands.allowed(player,"status")||(session.inventory.getSize()!=27&&layout.entrySlot()>=session.inventory.getSize())||session.inventory.getItem(session.inventory.getSize()==27?20:layout.entrySlot())!=null)return;session.inventory.setItem(session.inventory.getSize()==27?20:layout.entrySlot(),item(layout.icon(),player,"recovery-title",Map.of(),List.of()));session.actions.put(session.inventory.getSize()==27?20:layout.entrySlot(),()->open(player));}
    private boolean current(Player p,Session s){return p.isOnline()&&p.getUniqueId().equals(s.owner)&&p.getOpenInventory().getTopInventory().getHolder()==s;}
    private ItemStack item(Material material,Player p,String key,Map<String,String> values,List<net.kyori.adventure.text.Component> lore){var stack=new ItemStack(material);var meta=stack.getItemMeta();meta.displayName(messages.content(commands.language(p),key,values));meta.lore(lore.stream().map(line->line.colorIfAbsent(net.kyori.adventure.text.format.NamedTextColor.GRAY)).toList());stack.setItemMeta(meta);return stack;}
    void open(Player p){if(!layout.enabled()){commands.send(p,"recovery-gui-disabled",Map.of());return;}if(!commands.allowed(p,"status")){commands.send(p,"no-permission",Map.of());return;}var s=new Session(p.getUniqueId());s.inventory=Bukkit.createInventory(s,27,messages.content(commands.language(p),"recovery-title",Map.of()));p.openInventory(s.inventory);load(p,s,service.status(p.getUniqueId()));}
    private void load(Player p,Session session,java.util.concurrent.CompletionStage<RecoverySnapshot> future){session.busy=true;future.whenComplete((snapshot,error)->plugin.onMain(()->{if(!current(p,session))return;session.busy=false;if(error!=null){commands.failed(p,error);p.closeInventory();return;}render(p,session,snapshot);}));}
    private void render(Player p,Session s,RecoverySnapshot snapshot){int size=MenuGeometry.size(9+snapshot.objectives().size());if(s.inventory.getSize()!=size){s.inventory=Bukkit.createInventory(s,size,messages.content(commands.language(p),"recovery-title",Map.of()));p.openInventory(s.inventory);}s.inventory.clear();s.actions.clear();var l=commands.language(p);var values=commands.summary(snapshot,l);var lore=new ArrayList<net.kyori.adventure.text.Component>();lore.add(messages.content(l,"recovery-summary",values));lore.add(messages.content(l,"recovery-cooldown",values));for(var reward:snapshot.rewards())lore.add(messages.content(l,"recovery-reward",Map.of("stage",reward.stageId(),"amount",Long.toString(reward.reputation()),"time",reward.grantedAt().toString())));for(var stage:snapshot.proposedRewards())lore.add(messages.content(l,"recovery-proposed-reward",Map.of("stage",commands.translated(stage.names(),l),"amount",Long.toString(stage.reputation()))));
        Material stageIcon=java.util.Objects.requireNonNullElse(Material.matchMaterial(snapshot.stageIcon()),layout.icon());s.inventory.setItem(4,item(stageIcon,p,"recovery-title",Map.of(),lore));
        int index=0;for(var o:snapshot.objectives()){var v=Map.of("objective",commands.translated(o.names(),l),"description",commands.translated(o.descriptions(),l),"progress",Long.toString(o.progress()),"required",Long.toString(o.required()),"available",messages.plain(l,o.available()?"recovery-available":"recovery-unavailable"));s.inventory.setItem(9+index++,item(o.completed()?layout.completed():layout.objective(),p,"recovery-objective",v,List.of(messages.content(l,"recovery-objective-description",v))));}
        button(s,p,MenuGeometry.close(s.inventory.getSize()),Material.OAK_DOOR,"gui-close",()->p.closeInventory());button(s,p,MenuGeometry.back(s.inventory.getSize()),Material.ARROW,"gui-back",()->voting.open(p,p.getUniqueId(),p.getName()));
        if(commands.allowed(p,"start")&&snapshot.eligible())button(s,p,1,layout.startIcon(),"recovery-start",()->{if(commands.allowed(p,"start"))load(p,s,service.start(p.getUniqueId()));else commands.send(p,"no-permission",Map.of());});
        if(commands.allowed(p,"cancel")&&(snapshot.status()==RecoverySnapshot.Status.ACTIVE||snapshot.status()==RecoverySnapshot.Status.PAUSED))button(s,p,7,layout.cancelIcon(),"recovery-cancel",()->{if(commands.allowed(p,"cancel"))load(p,s,service.cancel(p.getUniqueId()));else commands.send(p,"no-permission",Map.of());});
    }
    private void button(Session s,Player p,int slot,Material material,String key,Runnable action){s.inventory.setItem(slot,item(material,p,key,Map.of(),List.of()));s.actions.put(slot,action);}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=false)public void click(InventoryClickEvent event){if(!(event.getView().getTopInventory().getHolder() instanceof Session s))return;event.setCancelled(true);if(!(event.getWhoClicked() instanceof Player p)||!current(p,s)||s.busy||!plugin.ready()||event.getClick()!=ClickType.LEFT||event.getRawSlot()<0||event.getRawSlot()>=s.inventory.getSize())return;long now=System.nanoTime();if(now-s.lastClick<250000000L)return;s.lastClick=now;var action=s.actions.get(event.getRawSlot());if(action!=null){s.busy=true;plugin.getServer().getScheduler().runTask(plugin,()->{if(current(p,s)&&plugin.ready()&&commands.allowed(p,"status")){s.busy=false;action.run();}});}}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=false)public void drag(InventoryDragEvent e){if(e.getView().getTopInventory().getHolder() instanceof Session)e.setCancelled(true);}
    void closeAll(){for(var p:plugin.getServer().getOnlinePlayers())if(p.getOpenInventory().getTopInventory().getHolder() instanceof Session)p.closeInventory();}
}
